from (values
('127.168.d.1.A',3,'A practicum student enrolls in a studio-lighting workshop offered by a local community college. This is:','["Training that builds employable skills", "A hobby only", "An unrelated class", "A way to avoid work"]'::jsonb,0,'Training/education/certification.','original'),
('127.168.d.1.A',4,'Earning a nationally recognized audio certification before graduation helps a graduate by:','["Avoiding interviews", "Showing employers verified skills", "Guaranteeing a salary", "Replacing a resume"]'::jsonb,1,'Certification.','original'),
('127.168.d.1.B',3,'A practicum student who is punctual, prepared, and respectful to clients is showing:','["Indifference", "Casual habits", "Professional standards", "Poor attitude"]'::jsonb,2,'Professional standards.','original'),
('127.168.d.1.B',4,'Which personal quality most helps a production assistant earn bigger responsibilities?','["Hiding mistakes", "Avoiding feedback", "Frequent excuses", "Reliability under pressure"]'::jsonb,3,'Personal qualities.','original'),
('127.168.d.1.C',3,'Finding a part-time job at a local TV station by checking its careers page is:','["Seeking employment", "Wasting time", "Quitting school", "Avoiding work"]'::jsonb,0,'Seeking employment.','original'),
('127.168.d.1.C',4,'Before an interview at a production company, a strong applicant should:','["Arrive empty-handed", "Practice answers and bring work samples", "Criticize past bosses", "Skip research"]'::jsonb,1,'Applying for employment.','original'),
('127.168.d.1.D',3,'Updating a portfolio each semester means:','["Deleting everything", "Adding only drafts", "Replacing weaker pieces with stronger recent work", "Never changing it"]'::jsonb,2,'Update career documents.','original'),
('127.168.d.1.D',4,'A cover letter updated for a new job posting should:','["List unrelated hobbies", "Repeat the same letter", "Be blank", "Match the employer''s stated needs"]'::jsonb,3,'Update documents.','original'),
('127.168.d.1.E',3,'Comparing pay, hours, benefits, and training when choosing between two offers is:','["Evaluating employment opportunities", "Gambling", "Daydreaming", "Procrastinating"]'::jsonb,0,'Compare employment.','original'),
('127.168.d.1.E',4,'A studio job with lower pay but a strong mentor program may be better for:','["Immediate retirement", "Rapid skill growth early in a career", "Avoiding experience", "Skipping training"]'::jsonb,1,'Evaluate opportunities.','original'),
('127.168.d.2.A',3,'Writing a clear production memo with correct spelling and punctuation shows:','["Random notes", "Only drawing", "Consistent English language arts skills", "Weak writing"]'::jsonb,2,'ELA.','original'),
('127.168.d.2.A',4,'A practicum student writes a press release for a school film. It needs a clear headline, key facts, and:','["Slang only", "Misspelled names", "No details", "Correct grammar and a contact name"]'::jsonb,3,'Writing for production.','original'),
('127.168.d.2.B',3,'A client is billed $65 per hour for 9 hours of editing. What is the invoice total?','["$585", "$650", "$520", "$74"]'::jsonb,0,'65 x 9 = 585.','original'),
('127.168.d.2.B',4,'A 4-hour studio session starts at 10:30 a.m. When does it end?','["1:30 p.m.", "2:30 p.m.", "12:30 p.m.", "3:30 p.m."]'::jsonb,1,'10:30 + 4 hours = 2:30 p.m.','original'),
('127.168.d.3.C',3,'A media class studies how film and TV can shape a viewer''s sense of self, relationships, and the world. This develops:','["Only camera skill", "Only editing speed", "Perception of self, human relationships, and the environment", "Only budgeting"]'::jsonb,2,'Perception of self through media.','original'),
('127.168.d.3.C',4,'A student reflects on how a documentary changed their view of their community. This is an example of media affecting:','["Cable length", "File size", "Frame rate", "A viewer''s understanding of the world"]'::jsonb,3,'Media and perception.','original'),
('127.168.d.3.C',3,'Exploring why a sad scene brings tears and a chase scene raises heartbeat studies the:','["Emotional and intellectual effects of visual media", "Storage", "Weather", "Voltage"]'::jsonb,0,'Effects of visual media.','original'),
('127.168.d.3.C',4,'A close-up of a character''s face with slow music mostly increases the viewer''s:','["Awareness of cables", "Emotional connection to the character", "Boredom", "Confusion about plot"]'::jsonb,1,'Emotional effect.','original'),
('127.168.d.3.A',3,'A voice actor practices clear pronunciation and breath control. This develops:','["Lighting skill", "Camera movement", "Effective voice and diction", "Set design"]'::jsonb,2,'Voice and diction.','original'),
('127.168.d.3.A',4,'Speaking at a steady pace with distinct consonants helps a narrator''s:','["Echo", "File size", "Frame rate", "Clarity and audience understanding"]'::jsonb,3,'Diction.','original'),
('127.168.d.3.B',3,'Advertising that uses stereotypes to sell a product can:','["Shape viewers'' attitudes in unfair ways", "Improve accuracy", "Cause no effect", "Reduce all bias"]'::jsonb,0,'Media strategies.','original'),
('127.168.d.3.B',4,'A media-literate viewer asks who made a message and why in order to:','["Accept everything", "Analyze persuasion strategies", "Hide the source", "Skip the message"]'::jsonb,1,'Analyze media.','original'),
('127.168.d.3.D',3,'A fast-cutting action trailer uses editing to create:','["Silence", "A sense of calm", "A sense of energy and urgency", "Empty frames"]'::jsonb,2,'Visual and audio techniques.','original'),
('127.168.d.3.D',4,'A low rumble before a monster appears is a sound technique used to build:','["Relief", "Boredom", "Humor", "Suspense"]'::jsonb,3,'Audio techniques.','original'),
('127.168.d.4.A',3,'A practicum student explains a camera test to the director using precise terms and to the client using plain terms. This is adapting language to:','["Audience, purpose, and situation", "A file name", "A tripod", "A battery"]'::jsonb,0,'Adapt language.','original'),
('127.168.d.4.A',4,'A producer shortens a technical report into a one-page summary for sponsors. This adapts language to the:','["Weather", "Purpose and intent", "Cable length", "Seat count"]'::jsonb,1,'Adapt language.','original'),
('127.168.d.4.B',3,'Grouping feedback comments into categories such as audio, picture, and pacing is:','["Deleting notes", "Hiding notes", "Analyzing and organizing information", "Printing notes"]'::jsonb,2,'Analyze and organize.','original'),
('127.168.d.4.B',4,'Creating a clear outline before a sponsor pitch helps the speaker:','["Confuse the audience", "Run overtime", "Skip the point", "Present ideas in a logical order"]'::jsonb,3,'Organize.','original'),
('127.168.d.4.C',3,'A producer studies audience-retention data and explains where viewers left. This is:','["Analyzing, interpreting, and communicating data", "Shooting B-roll", "Building sets", "Mixing sound"]'::jsonb,0,'Interpret data.','original'),
('127.168.d.4.C',4,'An editor notes that 60 percent of viewers leave in the first ten seconds. A smart communication of this fact is:','["Add a slower intro", "Recommend a stronger opening", "Ignore the result", "Remove the ending"]'::jsonb,1,'Communicate observations.','original'),
('127.168.d.4.D',3,'Designing a slide deck for a client pitch and presenting it live is a:','["Casual huddle", "Rehearsal only", "Formal presentation", "Private memo"]'::jsonb,2,'Create and deliver presentations.','original'),
('127.168.d.4.D',4,'A quick stand-up report on the day''s shoot is a(n):','["Awards show", "Keynote", "Press conference", "Informal presentation"]'::jsonb,3,'Informal presentation.','original'),
('127.168.d.4.E',3,'When a client gives vague notes, a producer should:','["Ask questions to clarify what they want", "Guess", "Argue", "Ignore the note"]'::jsonb,0,'Active listening.','original'),
('127.168.d.4.E',4,'Summarizing a director''s notes back at the end of a meeting confirms:','["Confusion", "Shared understanding", "Disagreement", "Delay"]'::jsonb,1,'Clarify information.','original'),
('127.168.d.4.F',3,'Interviewing a guest who is shy or uses a different dialect calls for:','["Teasing", "Dismissal", "Respect and patient listening", "Interrupting"]'::jsonb,2,'Diverse individuals.','original'),
('127.168.d.4.F',4,'Working with colleagues from different cultures benefits a production by:','["Creating conflict", "Ending teamwork", "Limiting ideas", "Adding fresh perspectives to stories"]'::jsonb,3,'Diversity.','original'),
('127.168.d.4.G',3,'On set, the person who performs in front of the camera is the:','["Talent", "Gaffer", "Script supervisor", "Grip"]'::jsonb,0,'Production roles.','original'),
('127.168.d.4.G',4,'Collaborating well with the director means the talent:','["Refuses notes", "Takes direction and gives feedback respectfully", "Ignores the director", "Changes the script silently"]'::jsonb,1,'Collaboration.','original'),
('127.168.d.4.H',3,'Internal customers for a studio include:','["Strangers", "Competitors", "Co-workers and departments that rely on your output", "Vendors only"]'::jsonb,2,'Internal customers.','original'),
('127.168.d.4.H',4,'Public relations that increases external customer satisfaction might include:','["Ignoring emails", "Hiding delays", "Arguing with clients", "Responding promptly and politely to client questions"]'::jsonb,3,'PR skills.','original'),
('127.168.d.5.A',3,'A team weighs two promotion ideas by cost, reach, and risk before choosing. That is:','["Critical thinking in a group", "Copying a rival", "Flipping a coin", "Guessing"]'::jsonb,0,'Critical thinking.','original'),
('127.168.d.5.A',4,'Testing two title designs with sample viewers before deciding relies on:','["The loudest opinion", "Evidence to support a choice", "Chance", "A hunch"]'::jsonb,1,'Critical thinking.','original'),
('127.168.d.5.B',3,'Mediating a disagreement between a camera operator and an editor needs:','["Shouting", "Taking sides", "Fair listening and compromise", "Ignoring it"]'::jsonb,2,'Interpersonal skills.','original'),
('127.168.d.5.B',4,'A good way to solve a crew scheduling conflict is to:','["Blame one person", "Leave it unresolved", "Cancel the shoot", "Meet, share constraints, and agree on a plan"]'::jsonb,3,'Group problem solving.','original'),
('127.168.d.5.C',3,'A student artist who revises a film after critique shows artistic discipline and:','["Responsibility for the quality of the work", "Indifference", "Carelessness", "Avoidance"]'::jsonb,0,'Responsibility and discipline.','original'),
('127.168.d.5.C',4,'Facing a creative problem when a location falls through, a good producer:','["Delays indefinitely", "Brainstorms alternatives and tests them", "Blames weather", "Gives up"]'::jsonb,1,'Creative problem solving.','original'),
('127.168.d.6.A',3,'A producer uses a shared calendar, email, and cloud folders to run a project. These are:','["Paper maps", "Obsolete tools", "Technology applications", "Hand tools"]'::jsonb,2,'Technology applications.','original'),
('127.168.d.6.A',4,'Using a messaging channel to post daily shoot updates helps the crew:','["Lose information", "Avoid contact", "Duplicate work", "Stay informed in real time"]'::jsonb,3,'Technology.','original'),
('127.168.d.6.B',3,'Setting up consistent folder structures for raw footage, audio, and exports is:','["File management", "Wardrobe", "Lens cleaning", "Casting"]'::jsonb,0,'File management.','original'),
('127.168.d.6.B',4,'Keeping a master contact list in one shared document is an example of:','["Duplicating errors", "Personal and information management", "Wasting memory", "Hiding information"]'::jsonb,1,'Information management.','original'),
('127.168.d.7.A',3,'Wearing proper footwear and following rules for heavy equipment throughout a practicum is:','["Ignoring rules", "Optional", "Implementing workplace safety rules", "Fashion"]'::jsonb,2,'Safety rules.','original'),
('127.168.d.7.A',4,'A lift-and-carry rule for a heavy light kit is typically to:','["Drag it", "Lift alone with a twisted back", "Throw it", "Use proper lifting technique or get help"]'::jsonb,3,'Safety.','original'),
('127.168.d.7.B',3,'A trip hazard from loose cables is recognized and resolved by:','["Taping or covering the cables", "Hiding them under a rug", "Moving them in front of exits", "Ignoring them"]'::jsonb,0,'Resolve safety concerns.','original'),
('127.168.d.7.B',4,'Before filming near water, a crew should recognize hazards such as:','["Cheap lunches", "Slippery surfaces and electrical risks", "Soft music", "Bright logos"]'::jsonb,1,'Recognize hazards.','original'),
('127.168.d.7.C',3,'If a fire alarm sounds during a shoot in a building, the crew should:','["Hide equipment", "Call the cast back", "Evacuate using the posted route", "Continue shooting"]'::jsonb,2,'Emergency procedures.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
